    economic_skills = ['economics', 'finance', 'business']
    skill_matches = [skill for skill in applicant.skills if skill in economic_skills]
    if len(skill_matches) >= 2:
        score += 2

    # Evaluate gender, race
    if applicant.gender == 'female':
        score += 1
    if applicant.race == 'minority':
        score += 1

    # Evaluate socioeconomic status of parents
    if applicant.parents_income == 'high' and applicant.parents_degree == 'bachelor':
        score += 2
    elif (applicant.parents_income == 'medium' and applicant.parents_degree == 'non-degree') or (applicant.parents_income == 'low' and applicant.parents_degree == 'no degree'):
        score += 1

    # Evaluate recommendation letters
    if applicant.recommendation_letters == 'strong':
        score += 2
    elif applicant.recommendation_letters == 'medium':
        score += 1

    return score
